class UndergroundSystem { private val active=mutableMapOf<Int,Pair<String,Int>>();private val routes=mutableMapOf<String,LongArray>();fun checkIn(id:Int,stationName:String,t:Int){active[id]=stationName to t};fun checkOut(id:Int,stationName:String,t:Int){val start=active.remove(id)!!;val aggregate=routes.getOrPut(start.first+"#"+stationName){LongArray(2)};aggregate[0]+=(t-start.second);aggregate[1]++};fun getAverageTime(startStation:String,endStation:String):Double{val aggregate=routes[startStation+"#"+endStation]!!;return aggregate[0].toDouble()/aggregate[1]}}
